INSERT INTO ai_credit_transactions (
    id, user_id, transaction_type, amount, plan_amount, purchased_amount,
    plan_balance_after, purchased_balance_after, reference_key, feature, trace_id,
    ai_api_call_id, cost_usd, reverses_transaction_id, note, created_by
) VALUES (
    #{tx.id}, #{tx.userId}, #{tx.transactionType}, #{tx.amount}, #{tx.planAmount}, #{tx.purchasedAmount},
    #{tx.planBalanceAfter}, #{tx.purchasedBalanceAfter}, #{tx.referenceKey}, #{tx.feature}, #{tx.traceId},
    #{tx.aiApiCallId}, #{tx.costUsd}, #{tx.reversesTransactionId}, #{tx.note}, #{tx.createdBy}
)

mapper.select:
SELECT 
FROM ai_credit_transactions t
WHERE t.trace_id = #{traceId}
  AND t.user_id = #{userId}
  AND t.transaction_type = 'CHARGE'
  AND NOT EXISTS (
      SELECT 1 FROM ai_credit_transactions r WHERE r.reverses_transaction_id = t.id
  )
ORDER BY t.created_at

SELECT 
FROM ai_credit_transactions
WHERE user_id = #{userId}
ORDER BY created_at DESC, id
LIMIT #{limit} OFFSET #{offset}
